/**
 * Superficie de L011/CONSMOVS: diez EXPORT con firma INTEGER PROCEDURE X(DATOS); EBCDIC ARRAY DATOS[*].
 * En Java cada entry point recibe un request tipado y devuelve un resultado con el mismo código
 * de retorno que esperan los consumidores (0, 1, 2, 3, 4, 5, 7, 9, 15).
 */
public interface ConsultaMovimientosDia {
    ResultadoControl     bdAccess(int funcion);                       // BDACCESS (98 cierra, otro abre)
    ResultadoTotales     totalesPorCaja(TotXCajaRequest req);         // TOTXCAJA
    ResultadoMovimientos movimientosTercerNivel(Movs3NivelRequest r); // MOVS3NIVEL
    ResultadoMovimientos movimientoEspecifico(MovEspecificoRequest r);// MOVESPECIFICO
    ResultadoMovimientos platino(PlatinoRequest req);                 // PLATINO
    ResultadoMovimientos porContratoS015(MovXCntRequest req);         // MOVXCNT
    ResultadoMovimientos ultimosMovimientos(UltimosMovsRequest req);  // CONS_4ULT
    ResultadoTotales     totalesPorSucursal(TotXSucRequest req);      // TOTXSUC
    ResultadoTotales     totalesCanalInteligente(TotalesCiRequest r); // TOTALESCI (punteo con NASC)
    ResultadoMovimientos consultaCanalInteligente(ConsultaCiRequest r);// CONSULTA_CI
}

@Service
@RequiredArgsConstructor
public class ConsultaMovimientosDiaService implements ConsultaMovimientosDia {

    private final CatalogoClavesTransaccion catalogo;   // ACLAVES, cargado en LEVANTA
    private final CalendarioDia calendario;             // FEC_DIA[0:9]

    /** LEVANTA: se ejecuta una vez al crear el bean, igual que antes de FREEZE(CONTROL,PROCTL). */
    @PostConstruct
    void levanta() {
        catalogo.cargar();
        calendario.cargar();
    }
    // CLOSE S151BD10MOVDIA151 al descongelar: lo hace el pool de conexiones en el shutdown del contexto.
}

