@Transactional(readOnly = true)
public interface MovimientoDiaRepository extends JpaRepository<MovimientoDia, MovimientoDiaId> { }

/**
 * B01BXMDA..B41BXMDA: mismo set en cinco juegos diarios. En el modelo relacional el juego
 * deja de ser un nombre de estructura y pasa a ser una columna de partición (numDia).
 */
public interface MovimientoDiaRepository extends JpaRepository<MovimientoDia, MovimientoDiaId> {

    /** FIND LAST + FIND PRIOR sobre BXMDA: recorrido descendente acotado. */
    @Query("""
           select m from MovimientoDia m
            where m.numDia = :numDia and m.moneda = :mda
              and m.sucursalMda = :sucursal and m.cuentaMda = :cuenta
            order by m.secuenciaSet desc
           """)
    Stream<MovimientoDia> ultimosPorMda(int numDia, int mda, int sucursal, String cuenta);

    /** FIND LAST + FIND PRIOR sobre BXMOVCTO. */
    @Query("""
           select m from MovimientoDia m
            where m.numDia = :numDia and m.contrato = :contrato
            order by m.secuenciaSet desc
           """)
    Stream<MovimientoDia> ultimosPorContrato(int numDia, String contrato);
}
